import { getDocument } from '../../utils/aws/s3.js';
import { getParameterValue } from '../../utils/aws/awsSSM.js';
import { getInstanceById } from '../../utils/aws/awsEc2.js';
import { MeteredAccount } from './meteringAccounts.entity.js';

const POOL_REFERENCE = 'pool/';
const UNIT_REFERENCE = 'unit/';
const ALIAS_REFERENCE = 'alias/';
const NODE_REFERENCE = 'node/';

/** Where the aliases a business points at other attribution material live. */
const ALIAS_PARAMETER_PREFIX = '/paigo/attribution/alias/';
/** The tag a metered resource carries the code it is booked to under. */
const CHARGE_CODE_TAG = 'paigoChargeCode';
/** The tag a metered resource names the owner it passes its cost on to under. */
const ROLLS_INTO_TAG = 'paigoRollsInto';

/**
 * One pocket of a business' estate. The finance system rewrites the whole set
 * whenever a team moves, so the pools are kept together in a single document
 * rather than one object each.
 */
export class AttributionPool {
    /** The code spend sitting on this pool is booked to. */
    public chargeCode: string;
    /**
     * The owner this pool hands its cost on to, when it does not keep it. The
     * pool's own code is only an intermediate stop in that case.
     * @example "unit/ember"
     */
    public rollsUpTo?: string;
}

export class AttributionPoolDocument {
    public revision: string;
    public pools: Record<string, AttributionPool>;
}

/**
 * A business unit, kept as one object each because finance edits them
 * one at a time.
 */
export class AttributionUnitDocument {
    public unitId: string;
    /** The code spend sitting on this unit is booked to. */
    public chargeCode: string;
    /**
     * The owner this unit hands its cost on to, when it does not keep it.
     * @example "alias/zircon"
     */
    public parentRef?: string;
}

/**
 * One stop along the chain a usage line's attribution walks: the code the stop
 * books to, plus the owner it hands the cost on to when it is only passing it
 * through.
 */
class AttributionStop {
    public reference: string;
    public chargeCode?: string;
    public passesTo?: string;
}

/**
 * The code every stop of a repeating chain agrees on. A chain that turns back
 * on itself has no end to book against, so the cycle's own shared code carries
 * the spend.
 */
const sharedChargeCodeOf = (cycle: Array<AttributionStop>): string => {
    const counts = new Map<string, number>();
    cycle.forEach(({ chargeCode }) => {
        if (chargeCode) {
            counts.set(chargeCode, (counts.get(chargeCode) ?? 0) + 1);
        }
    });
    let shared: string;
    let seenTimes = 0;
    counts.forEach((times, chargeCode) => {
        if (times > seenTimes) {
            shared = chargeCode;
            seenTimes = times;
        }
    });
    return shared;
};

/** The last code the walk passed, used when a chain runs into a dead end. */
const lastKnownChargeCodeOf = (walked: Array<AttributionStop>): string =>
    [...walked].reverse().find(({ chargeCode }) => chargeCode)?.chargeCode;

/**
 * The attribution material a business keeps beside its onboarding record.
 *
 * A usage line names where its attribution starts, and that starting point may
 * hand the cost on to another owner, which may hand it on again. The directory
 * walks the whole chain so spend lands on the code that ultimately carries it
 * rather than on the first stop it passed through.
 */
export class AttributionDirectory {
    private readonly pools: Record<string, AttributionPool>;

    private readonly bucket: string;

    private readonly prefix: string;

    private readonly accounts: Record<string, MeteredAccount>;

    private readonly credentialsFor: (account: MeteredAccount) => any;

    /** Chains are shared by many lines, so each stop is only looked up once. */
    private readonly stops = new Map<string, Promise<AttributionStop>>();

    private readonly resolved = new Map<string, Promise<string>>();

    private constructor(
        pools: Record<string, AttributionPool>,
        bucket: string,
        prefix: string,
        accounts: Array<MeteredAccount>,
        credentialsFor: (account: MeteredAccount) => any,
    ) {
        this.pools = pools;
        this.bucket = bucket;
        this.prefix = prefix;
        this.accounts = (accounts ?? []).reduce((acc, account) => {
            acc[account.accountId] = account;
            return acc;
        }, {});
        this.credentialsFor = credentialsFor;
    }

    /**
     * @param accounts The accounts the business handed us, needed for the
     * stretches of a chain that live on a metered resource.
     * @param credentialsFor How to read one of those accounts.
     */
    static async load(
        bucket: string,
        prefix: string,
        accounts: Array<MeteredAccount> = [],
        credentialsFor: (account: MeteredAccount) => any = () => undefined,
    ): Promise<AttributionDirectory> {
        const document = await getDocument<AttributionPoolDocument>(bucket, `${prefix}pools.json`);
        return new AttributionDirectory(document?.pools ?? {}, bucket, prefix, accounts, credentialsFor);
    }

    /**
     * The charge code named by the attribution reference a usage line carries,
     * without following anything that reference passes its cost on to.
     */
    chargeCodeFor(reference: string): string {
        if (!reference || !reference.startsWith(POOL_REFERENCE)) {
            return undefined;
        }
        return this.pools[reference.slice(POOL_REFERENCE.length)]?.chargeCode;
    }

    /**
     * The code that ultimately carries the spend of a line starting at the
     * given reference, following every hand off along the way. A chain that
     * repeats books to the code its cycle shares, and one that runs into
     * material we cannot read books to the last code it did reach.
     */
    async finalChargeCodeFor(reference: string): Promise<string> {
        if (!reference) {
            return undefined;
        }
        if (!this.resolved.has(reference)) {
            this.resolved.set(reference, this.walkFrom(reference));
        }
        return this.resolved.get(reference);
    }

    private async walkFrom(reference: string): Promise<string> {
        const walked: Array<AttributionStop> = [];
        const visited = new Map<string, number>();
        let current = reference;

        while (current) {
            if (visited.has(current)) {
                const cycle = walked.slice(visited.get(current));
                return sharedChargeCodeOf(cycle) ?? lastKnownChargeCodeOf(walked);
            }
            visited.set(current, walked.length);
            // Each stop of a chain can only be looked up once the one before it is known.
            // eslint-disable-next-line no-await-in-loop
            const stop = await this.stopAt(current);
            if (!stop) {
                // The chain names material we cannot read, so it ends where we last could.
                return lastKnownChargeCodeOf(walked);
            }
            walked.push(stop);
            if (!stop.passesTo) {
                return stop.chargeCode ?? lastKnownChargeCodeOf(walked);
            }
            current = stop.passesTo;
        }
        return lastKnownChargeCodeOf(walked);
    }

    private async stopAt(reference: string): Promise<AttributionStop> {
        if (!this.stops.has(reference)) {
            this.stops.set(reference, this.lookUpStop(reference));
        }
        return this.stops.get(reference);
    }

    private async lookUpStop(reference: string): Promise<AttributionStop> {
        if (reference.startsWith(POOL_REFERENCE)) {
            const pool = this.pools[reference.slice(POOL_REFERENCE.length)];
            return pool ? { reference, chargeCode: pool.chargeCode, passesTo: pool.rollsUpTo } : undefined;
        }
        if (reference.startsWith(UNIT_REFERENCE)) {
            return this.unitStop(reference);
        }
        if (reference.startsWith(ALIAS_REFERENCE)) {
            return this.aliasStop(reference);
        }
        if (reference.startsWith(NODE_REFERENCE)) {
            return this.nodeStop(reference);
        }
        return undefined;
    }

    private async unitStop(reference: string): Promise<AttributionStop> {
        const unit = reference.slice(UNIT_REFERENCE.length);
        try {
            const document = await getDocument<AttributionUnitDocument>(
                this.bucket,
                `${this.prefix}units/${unit}.json`,
            );
            return document ? { reference, chargeCode: document.chargeCode, passesTo: document.parentRef } : undefined;
        } catch (error) {
            return undefined;
        }
    }

    /**
     * An alias is only a name for another owner, so it books nothing itself.
     */
    private async aliasStop(reference: string): Promise<AttributionStop> {
        const alias = reference.slice(ALIAS_REFERENCE.length);
        const passesTo = await getParameterValue(`${ALIAS_PARAMETER_PREFIX}${alias}`);
        return passesTo ? { reference, passesTo } : undefined;
    }

    /**
     * A stretch of a chain that lives on a metered resource, named as
     * `node/{accountId}/{region}/{resourceId}`. Only the accounts the business
     * onboarded can be read, and the resource carries its code and any hand off
     * as tags.
     */
    private async nodeStop(reference: string): Promise<AttributionStop> {
        const [accountId, region, resourceId] = reference.slice(NODE_REFERENCE.length).split('/');
        const account = this.accounts[accountId];
        if (!account || !region || !resourceId) {
            return undefined;
        }
        const instance = await getInstanceById(region, this.credentialsFor(account), resourceId);
        if (!instance) {
            return undefined;
        }
        const tags = (instance.Tags ?? []).reduce((acc, { Key, Value }) => {
            acc[Key] = Value;
            return acc;
        }, {});
        return { reference, chargeCode: tags[CHARGE_CODE_TAG], passesTo: tags[ROLLS_INTO_TAG] };
    }
}
